const grafana=()=>`<section class="section grafana"><div class="wrap"><div class="section-head"><p class="section-label">Community integration</p><h2>Optional Grafana workflow.</h2></div><div class="grafana-grid"><div class="grafana-copy"><p>This community-built integration can place Lians evidence beside operational telemetry. It is available as buildable source, but it is not catalog-listed, reviewed, approved, or endorsed by Grafana Labs.</p><a class="button" href="https://github.com/Lians-ai/Lians/tree/master/integrations/grafana-lians-app" target="_blank" rel="noreferrer">View community source ↗</a></div><div class="pipeline"><div class="pipe-row"><span>CORE / SUPPORTED</span><strong>OpenTelemetry into Lians</strong><p>Standard spans from agents, models, tools, and reviewers.</p></div><div class="pipe-row"><span>OPTIONAL / COMMUNITY</span><strong>Grafana adapter</strong><p>Use the source directly while external catalog review remains pending.</p></div><div class="pipe-row"><span>STATUS</span><strong>No vendor endorsement</strong><p>Grafana Labs has not reviewed or signed off on this integration.</p></div></div></div></div></section>`;
const outcomes=()=>`<section class="section"><div class="wrap"><div class="section-head"><p class="section-label">Focused outcomes</p><h2>Built for the moment “what happened?” is not enough.</h2></div><div class="outcomes"><article class="outcome"><span>INCIDENT REVIEW</span><h3>Reconstruct the exact run</h3><p>See the model, prompt context, tools, outputs, and reviews as they existed when the event occurred.</p></article><article class="outcome"><span>MODEL OPERATIONS</span><h3>Trace behavior across versions</h3><p>Compare production behavior by model, agent, policy, and release without losing the historical record.</p></article><article class="outcome"><span>RISK & COMPLIANCE</span><h3>Export evidence, not screenshots</h3><p>Produce a verifiable package of linked events, provenance, review actions, and integrity checks.</p></article><article class="outcome"><span>ENGINEERING</span><h3>Instrument once</h3><p>Use OpenTelemetry and Grafana instead of adopting another closed monitoring stack.</p></article></div></div></section>`;
