const product=()=>pageShell(`<section class="story-system"><div class="wrap">
  <article class="story-row"><div class="story-copy"><span>01 / RECORD</span><h2>Record the changing inputs.</h2><p>Store facts, permissions, policies, tool results, and decisions with provenance, event time, and system time intact.</p></div><div class="evidence-artifact trace-artifact" aria-label="A linked decision record"><header><span>DECISION / CREDIT-2048</span><b>4 LINKED RECORDS</b></header><div><time>14:32:08</time><i></i><strong>identity.result</strong><em>recorded</em></div><div><time>14:32:09</time><i></i><strong>revenue.v3</strong><em>linked</em></div><div><time>14:32:10</time><i></i><strong>policy.v4</strong><em>preserved</em></div><div><time>14:32:11</time><i></i><strong>decision</strong><em>verified</em></div></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>02 / PRESERVE</span><h2>Keep every source revision.</h2><p>Later facts can supersede earlier ones without erasing what was available when the AI acted.</p></div><div class="evidence-artifact clock-artifact" aria-label="Event time and system time record"><header><span>FACT / REVENUE</span><b>VERSION HISTORY</b></header><div class="clock-axis"><small>EVENT TIME</small><i></i><strong>2026-01-12</strong></div><div class="clock-axis"><small>SYSTEM TIME</small><i></i><strong>2026-01-15</strong></div><footer><span>v3</span><p>source and prior value preserved</p><b>HASH 18DF</b></footer></div></article>
  <article class="story-row"><div class="story-copy"><span>03 / RECONSTRUCT</span><h2>Open the past cleanly.</h2><p>Query the record as it existed at a prior moment and exclude every revision or fact learned after the decision.</p></div><div class="evidence-artifact window-artifact" aria-label="A point-in-time reconstruction window"><header><span>AS OF / 14:32:11</span><b>HISTORICAL VIEW</b></header><div class="window-track"><i></i><span>DECISION</span><em>REVISION EXCLUDED</em></div><div class="window-facts"><p><i></i>Identity verified <b>KNOWN</b></p><p><i></i>Revenue v3 <b>KNOWN</b></p><p class="future"><i></i>Revenue v4 <b>FUTURE</b></p></div></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>04 / VERIFY</span><h2>Produce a decision receipt.</h2><p>Export the included source versions, excluded future items, and integrity checks needed to reproduce the result.</p></div><div class="evidence-artifact receipt-artifact" aria-label="A verified decision receipt"><div class="receipt-mark">✓</div><span>DECISION RECEIPT</span><h3>Verification passed.</h3><dl><div><dt>Decision</dt><dd>credit-2048</dd></div><div><dt>Sources</dt><dd>3 linked</dd></div><div><dt>Chain</dt><dd>18df…91a2</dd></div></dl></div></article>
</div></section>`);
