const about=()=>pageShell(`<section class="story-system about-system"><div class="wrap">
  <article class="story-row"><div class="story-copy"><span>THE GAP</span><h2>Agents forget, overwrite, and repeat mistakes.</h2><p>Long-running agents need more than a vector search result. They need memory that understands time, preserves conflict, and connects later outcomes back to earlier context.</p></div><div class="evidence-artifact compare-artifact" aria-label="Difference between retrieval and durable memory"><header><span>RETRIEVAL</span><b>MEMORY</b></header><div><p>Similar text</p><i>→</i><p>Relevant context</p></div><div><p>Latest value</p><i>→</i><p>Version history</p></div><div><p>Static ranking</p><i>→</i><p>Outcome signals</p></div><footer>FIND SOMETHING <i>→</i> REMEMBER RESPONSIBLY</footer></div></article>
  <article class="story-row reverse"><div class="story-copy"><span>THE FOCUS</span><h2>Build a better memory loop.</h2><p>Lians joins durable knowledge, task-specific context, outcome learning, and evidence in one system so agents can improve without making their history opaque.</p></div><div class="evidence-artifact flow-artifact" aria-label="Lians memory loop"><div><span>01</span><b>Remember</b><small>Facts and experience</small></div><i>→</i><div><span>02</span><b>Recall</b><small>Context for the task</small></div><i>→</i><div><span>03</span><b>Learn</b><small>Outcomes improve recall</small></div></div></article>
  <article class="story-row"><div class="story-copy"><span>THE BOUNDARY</span><h2>Open at the edges.</h2><p>Lians is SDK-friendly, OpenTelemetry-native, open source, API-accessible, and self-hostable.</p></div><div class="evidence-artifact edge-artifact" aria-label="Open integration boundaries"><div class="edge-core"><img src="/logo-blue.png" alt="Lians"></div><span class="edge-node edge-node-a" aria-label="SDK: Add memory and context to Python and TypeScript agents.">SDK<span class="edge-tip" aria-hidden="true">Add memory and context to Python and TypeScript agents.</span></span><span class="edge-node edge-node-b" aria-label="API: Write, recall, learn from, and govern memory through a focused API.">API<span class="edge-tip" aria-hidden="true">Write, recall, learn from, and govern memory through a focused API.</span></span><span class="edge-node edge-node-c" aria-label="Export: Produce portable lineage and verifiable receipts for review.">EXPORT<span class="edge-tip" aria-hidden="true">Produce portable lineage and verifiable receipts for review.</span></span><span class="edge-node edge-node-d" aria-label="Self-host: Keep the memory boundary inside infrastructure you control.">SELF-HOST<span class="edge-tip" aria-hidden="true">Keep the memory boundary inside infrastructure you control.</span></span></div></article>
</div></section>`);
const pilot=()=>pageShell(`<div class="wrap content-grid content-grid-wide"><main class="prose"><h2>Bring us one agent that needs durable memory.</h2><p>We map what it should remember, define the context and learning loop, connect the production path, and verify the result against an acceptance suite.</p><form class="pilot-form" id="partner-application"><div class="form-grid"><label>Work email<input type="email" name="work_email" autocomplete="email" required></label><label>Company<input name="company" autocomplete="organization" required></label><label>Role<input name="role" autocomplete="organization-title" required></label><label>Company website<input type="url" name="company_website" placeholder="https://" required></label></div><label>What does the agent do?<textarea name="agent_workflow" required></textarea></label><label>What should it remember or learn over time?<textarea name="changing_facts" required></textarea></label><label>What must your team inspect, reconstruct, or prove?<textarea name="audit_requirement" required></textarea></label><div class="form-grid"><label>Current stage<select name="current_stage" required><option value="">Select one</option><option>Prototype</option><option>Pilot</option><option>Production</option></select></label><label>Preferred engagement<select name="preferred_track" required><option value="">Select one</option><option>Implementation</option><option>Evaluation</option><option>Unsure</option></select></label><label>Deployment requirement<select name="deployment_requirement" required><option value="">Select one</option><option>Cloud</option><option>Private cloud</option><option>Self-hosted</option><option>Air-gapped</option></select></label><label>Architecture or example (optional)<input type="file" name="architecture_file" accept=".pdf,.txt,.md,.png,.jpg,.jpeg"></label></div><input type="hidden" name="utm_source"><input type="hidden" name="utm_medium"><input type="hidden" name="utm_campaign"><input type="hidden" name="utm_term"><input type="hidden" name="utm_content"><input type="hidden" name="landing_page"><input type="hidden" name="referring_url"><div class="hero-actions"><button class="button button-primary" type="submit">Plan your implementation →</button><span id="partner-form-status" role="status"></span></div></form><div id="partner-form-success" hidden><h3>Request received.</h3><p>We will review the workflow and reply with a direct fit assessment.</p><a id="partner-booking-link" hidden>Schedule a fit call →</a></div></main></div>`);
const legal=(name)=>pageShell(`<div class="wrap content-grid"><aside class="toc">${name.toUpperCase()}</aside><main class="prose"><h2>${name}</h2><p>This page is being consolidated as part of the Lians website simplification. Existing contractual terms remain controlling. Contact <a href="mailto:hello@lians.ai">hello@lians.ai</a> for the current policy or agreement.</p></main></div>`);
const security=()=>pageShell(`<section class="section security-system"><div class="wrap"><div class="security-boundary"><div><h2>Keep the memory boundary explicit.</h2><p>Store only what the agent requires, choose where it runs, and keep every privileged action attributable.</p></div><div class="boundary-map" aria-label="Security and deployment boundary"><span class="boundary-input">Agent context</span><i>→</i><div><b>YOUR MEMORY BOUNDARY</b><strong>Lians</strong><small>private cloud · self-hosted · managed</small></div><i>→</i><span class="boundary-output">Attributed recall</span></div></div><div class="security-grid"><article><span>01</span><h2>Control the boundary.</h2><p>Choose which facts and messages enter memory. Deploy self-hosted when agent context cannot leave your environment.</p></article><article><span>02</span><h2>Verify integrity.</h2><p>Append-only audit events and linked hashes make later changes detectable. Verification results travel with exported lineage.</p><div class="hash-line"><i>7f2a</i><b>→</b><i>b91c</i><b>→</b><i>18df</i></div></article><article><span>03</span><h2>Limit access.</h2><p>Scoped API keys, namespace isolation, information barriers, and review controls keep memory access explicit and attributable.</p><div class="scope-list"><span>memory:read</span><span>memory:write</span><span>review:approve</span></div></article><article><span>04</span><h2>Ask before assuming.</h2><p>Security requirements vary. We document the exact deployment, controls, and responsibilities before implementation begins.</p></article></div><div class="security-contact"><p>No implied certifications. No inherited vendor claims.</p><a class="button" href="mailto:security@lians.ai">Contact security →</a></div></div></section>`);
