  {date:"09:42:11",state:"DECISION MADE",answer:"Approved · risk within policy",note:"Only facts available when the decision was made are included.",facts:[["Identity verified","Known","good"],["Annual revenue · $1.2m","Known","good"],["Risk policy v4","Known","good"],["Revenue revision · $780k","Future","future"]]},
  {date:"11:16:04",state:"SOURCE REVISED",answer:"Original decision preserved",note:"The later revision is visible, but cannot leak into the historical reconstruction.",facts:[["Identity verified","Known","good"],["Annual revenue · $1.2m","Superseded","muted"],["Risk policy v4","Known","good"],["Revenue revision · $780k","Arrived later","future"]]},
  {date:"NOW",state:"RECONSTRUCTED",answer:"Approved · based on the 09:42 record",note:"The full revision chain is present and the original decision remains reproducible.",facts:[["Identity verified","Verified","good"],["Annual revenue · $1.2m","Historical","good"],["Risk policy v4","Verified","good"],["Revenue revision · $780k","Excluded","future"]]}
